 *
 * platform in {Referral, Talent Pool}: not externally sourceable — these are
 * internal-pipeline concepts, not searched at all.
 *
 * Read-only throughout: never writes to GitHub, never logs into or scrapes a
 * platform, never posts a message.
 *
 * `username` (optional): manual single-profile intake. When present, `query`
 * is ignored entirely and the request resolves that one GitHub login via
 * GET /users/{login} instead of running a search.
 */
const GITHUB_USERNAME_RE = /^[a-zA-Z\d](?:[a-zA-Z\d]|-(?=[a-zA-Z\d])){0,38}$/;

const SourceSchema = z
  .object({
    query: z.string().min(1).max(256).optional(),
    username: z.string().min(1).max(39).regex(GITHUB_USERNAME_RE, "Not a valid GitHub username.").optional(),
    count: z.number().int().min(1).max(20).default(8),
    platform: z.enum(SOURCE_PLATFORMS).default("GitHub"),
  })
  .refine((data) => Boolean(data.username?.trim()) || Boolean(data.query?.trim()), {
    message: "query or username is required.",
    path: ["query"],
  });

function publicDemoSourceDenied(req: NextRequest): Response | null {
  if (supabaseEnabled || !demoLoginEnabled) return null;
  if (demoAuthConfigured() && verifyDemoToken(req.cookies.get(DEMO_COOKIE_NAME)?.value)) return null;
  return NextResponse.json({ ok: false, error: "Sign in to use live sourcing." }, { status: 401 });
}

export async function POST(req: NextRequest) {
  const prodBlock = prodFailClosed();
  if (prodBlock) return prodBlock;
  const demoBlock = publicDemoSourceDenied(req);
  if (demoBlock) return demoBlock;

  const rl = checkRateLimit(rateLimitKey(req, "source"), { windowMs: 60_000, max: 10 });
  if (!rl.ok) return tooManyRequests(rl.retryAfterSec);

  // Live mode: require an authenticated user with the `source` permission. Demo
  // mode (no backend) is open but still rate-limited.
  if (supabaseEnabled) {
    const supabase = await getServerSupabase();
    if (!supabase) return NextResponse.json({ ok: false, error: "No Supabase client." }, { status: 500 });
    const {
      data: { user },
    } = await supabase.auth.getUser();
    if (!user) return NextResponse.json({ ok: false, error: "Not authenticated." }, { status: 401 });
    const { data: role } = await supabase.rpc("current_profile_role");
    if (!can(role as Role, "source")) {
      return NextResponse.json({ ok: false, error: "Insufficient permissions." }, { status: 403 });
    }
  }

  const validated = await validateBody(req, SourceSchema, { maxBytes: 10_000 });
  if (!validated.ok) return validated.response;
  const { query, username, count = 8, platform = "GitHub" as const } = validated.data;

  // Manual single-profile intake: resolve exactly the named GitHub login,
  // ignoring `query` and `count` entirely — this is a lookup, not a search.
  if (username) {
    const token = process.env.GITHUB_TOKEN ?? "";
    try {
      const user = await getGithubUser(username, token);
      if (!user) {
        return NextResponse.json({ ok: false, error: "GitHub user not found." }, { status: 404 });
      }
      return NextResponse.json({ ok: true, source: "github", users: [user] });
    } catch (err) {
      const detail = err instanceof Error ? err.message : "GitHub lookup failed.";
      return NextResponse.json({ ok: false, source: "github", error: detail }, { status: 502 });
    }
  }

  // Schema-enforced: username or query is present; username was handled above.
  if (!query) return NextResponse.json({ ok: false, error: "query is required." }, { status: 400 });

  if (platform === "GitHub") {
    const token = process.env.GITHUB_TOKEN ?? "";
    try {
      const users = await searchGithubUsers(query, count, token);
      return NextResponse.json({ ok: true, source: "github", platform, users });
    } catch (err) {
      // GitHub error bodies never contain the token; keep the client message terse.
      const detail = err instanceof Error ? err.message : "GitHub search failed.";
      return NextResponse.json({ ok: false, source: "github", platform, error: detail }, { status: 502 });
    }
  }

  if (isWebSearchPlatform(platform)) {
    const result = await runWebTool("web_search", { query });
    if (!result.ok) {
      return NextResponse.json(
        { ok: false, source: "web", platform, error: result.error ?? "Web search failed." },
        { status: 502 },
      );
    }
    const content = result.content as { results?: { title: string; url: string; snippet: string }[] } | undefined;
    const hits = (content?.results ?? []).slice(0, count);
    const leads: WebLead[] = hits.map((h) => extractLead(h, platform));
    return NextResponse.json({ ok: true, source: "web", platform, leads });
  }

  // Referral / Talent Pool: internal-pipeline concepts, no external source to search.
  return NextResponse.json({ ok: true, source: "mock", platform, users: [] as GithubUser[] });
}

/**
 * Real connection test for GitHub sourcing. With a token: pings GET /user and
 * reports the authenticated identity. Without one: pings the keyless GET
 * /rate_limit endpoint (works anonymously) and reports the live 60 req/hour
 * quota, so the UI shows real connectivity rather than "add a token to go live" —
 * a token is an optional upgrade, not a requirement. Never returns the token.
 */
export async function GET(req: NextRequest) {
  const prodBlock = prodFailClosed();
  if (prodBlock) return prodBlock;
  const demoBlock = publicDemoSourceDenied(req);
  if (demoBlock) return demoBlock;

  const rl = checkRateLimit(rateLimitKey(req, "source-probe"), { windowMs: 60_000, max: 20 });
  if (!rl.ok) return tooManyRequests(rl.retryAfterSec);

  if (supabaseEnabled) {
    const supabase = await getServerSupabase();
    if (!supabase) return NextResponse.json({ ok: false, error: "No Supabase client." }, { status: 500 });
    const {
      data: { user },
    } = await supabase.auth.getUser();
    if (!user) return NextResponse.json({ ok: false, error: "Not authenticated." }, { status: 401 });
    const { data: role } = await supabase.rpc("current_profile_role");
    if (!can(role as Role, "source")) {
      return NextResponse.json({ ok: false, error: "Insufficient permissions." }, { status: 403 });
    }
  }

  const token = process.env.GITHUB_TOKEN ?? "";

  if (!token) {
    try {
      const res = await fetch("https://api.github.com/rate_limit", {
        headers: { Accept: "application/vnd.github+json", "User-Agent": "aria-sourcing" },
        signal: AbortSignal.timeout(10_000),
      });
      if (!res.ok) {
        return NextResponse.json({ ok: true, connected: false, reason: `GitHub unreachable (${res.status}).` });
      }
      const body = (await res.json().catch(() => ({}))) as {
        resources?: { search?: { remaining?: number; limit?: number } };
      };
      const search = body.resources?.search;
      return NextResponse.json({
        ok: true,
        connected: true,
        login: null,
        name: null,
        anonymous: true,
        rateLimitRemaining: search?.remaining ?? null,
        rateLimitTotal: search?.limit ?? null,
        reason: "Sourcing anonymously (60 req/hour). Add GITHUB_TOKEN for a higher ceiling (5,000 req/hour).",
      });
    } catch {
      return NextResponse.json({ ok: true, connected: false, reason: "GitHub unreachable." });
    }
  }

  try {
    const res = await fetch("https://api.github.com/user", {
      headers: {
        Authorization: `Bearer ${token}`,
        Accept: "application/vnd.github+json",
        "X-GitHub-Api-Version": "2022-11-28",
        "User-Agent": "aria-sourcing",
      },
      signal: AbortSignal.timeout(10_000),
    });
    if (!res.ok) {
      return NextResponse.json({ ok: true, connected: false, reason: `GitHub token rejected (${res.status}).` });
    }
    const u = (await res.json().catch(() => ({}))) as { login?: string; name?: string; public_repos?: number };
    return NextResponse.json({
      ok: true,
      connected: true,
      login: u.login ?? "unknown",
      name: u.name ?? null,
      anonymous: false,
      publicRepos: u.public_repos ?? 0,
    });
  } catch {
    return NextResponse.json({ ok: true, connected: false, reason: "GitHub unreachable." });
  }
}

import { NextResponse, type NextRequest } from "next/server";
import { z } from "zod";
import { getServerSupabase } from "@/lib/supabase/server";
import { supabaseEnabled, prodFailClosed, demoLoginEnabled, DEMO_COOKIE_NAME } from "@/lib/supabase/config";
import { demoAuthConfigured, verifyDemoToken } from "@/lib/demo-auth";
import { validateBody } from "@/lib/api/validate";
import { can } from "@/lib/rbac";
import type { Campaign, Candidate, Role, ScoringWeights } from "@/lib/types";
import { DEFAULT_MODEL, PROVIDER_ENV, type AiProviderSlug } from "@/lib/ai/provider";
import { resolveVaultSecret } from "@/lib/ai/vault-secret";
import { runAnthropicWithTools, runOpenAiWithTools, type ResolvedMcpServer } from "@/lib/ai/tool-loop";
import { SOURCING_TOOL_DEFS, makeSourcingToolRunner } from "@/lib/ai/sourcing-tools";
import { checkRateLimit, rateLimitKey, tooManyRequests } from "@/lib/rate-limit";

export const dynamic = "force-dynamic";

/**
 * Agentic sourcing: one tool-calling loop that searches real platforms, scores
 * real candidates (deterministic — see sourcing-tools.ts), and drafts outreach
 * for the best matches, instead of the client stitching separate calls one at
 * a time. TEXT + TOOL CALLS ONLY — like /api/hermes/chat, this never sends
 * anything; drafts still go through the same human approval gate as any other
 * outreach message.
 *
 * Only providers with real function-calling get this (no "hermes"/"kimi" — the
 * hermes runtime path and Kimi Code don't support the tools param).
 */
const AGENT_PROVIDERS = ["anthropic", "openai", "groq", "xai", "mistral"] as const;

const SourcingAgentSchema = z.object({
  // Full client-owned objects, passed through — the client already has these
  // in its local state; this route is stateless per-request, same posture as
  // /api/source (which receives a client-built query string rather than
  // looking up campaign data server-side).
  campaign: z.record(z.string(), z.unknown()),
  existing: z.array(z.record(z.string(), z.unknown())).max(500).default([]),
  count: z.number().int().min(1).max(8).default(5),
  provider: z.enum(AGENT_PROVIDERS),
  apiKeyId: z.string().uuid().optional(),
  model: z.string().regex(/^[a-zA-Z0-9][a-zA-Z0-9._-]{0,79}$/).optional(),
});

const SYSTEM_PROMPT =
  "You are Aria's autonomous sourcing agent. You have a search_candidates tool that returns REAL, " +
  "already-scored people found via real platform search — you never invent a candidate, a score, a " +
  "company, or a URL. Call it across the platforms that make sense for this role (skip ones with no " +
  "real fit — e.g. don't search Dribbble for a backend engineer). Call it more than once per platform " +
  "with a different query if the first pass returns too few strong matches. Once you've gathered enough " +
  "real, well-scored candidates, stop calling tools and respond with ONLY this JSON (no prose, no markdown " +
  "fences): {\"drafts\": [{\"candidateId\": \"<id from a tool result>\", \"subject\": \"<email subject>\", " +
  "\"body\": \"<first-touch outreach, under 120 words, leads with their specific real work, one genuine " +
  "reason for reaching out, soft low-pressure ask, no AI slop, no corporate filler, no em-dashes>\"}]}. " +
  "Draft for the requested number of candidates, choosing the best-scored real matches you found. Every " +
  "candidateId MUST be one that a search_candidates result actually returned.";

function buildPrompt(campaign: Campaign, count: number): string {
  const jd = campaign.jobAnalysis;
  return [
    `Role: ${jd.title} (${jd.seniority}, ${jd.department})`,
    `Location: ${jd.locationType}${jd.regions.length ? ` — ${jd.regions.join("/")}` : ""}`,
    `Required skills: ${jd.requiredSkills.join(", ") || "n/a"}`,
    `Nice-to-have: ${jd.niceToHaveSkills.join(", ") || "n/a"}`,
    jd.minYearsExperience != null ? `Minimum experience: ${jd.minYearsExperience} years` : "",
    jd.companyStageTarget.length ? `Target company stage: ${jd.companyStageTarget.join(", ")}` : "",
    jd.industryExperience.length ? `Industry experience: ${jd.industryExperience.join(", ")}` : "",
    "",
    `Find and draft outreach for ${count} real candidates for this role.`,
  ]
    .filter(Boolean)
    .join("\n");
}

/** Parse the model's final JSON, tolerant of stray text/markdown fences around it. */
function parseDrafts(text: string): { candidateId: string; subject: string; body: string }[] {
  const match = text.match(/\{[\s\S]*\}/);
  if (!match) return [];
  try {
    const parsed = JSON.parse(match[0]) as { drafts?: unknown };
    if (!Array.isArray(parsed.drafts)) return [];
    return parsed.drafts
      .filter(
        (d): d is { candidateId: string; subject: string; body: string } =>
          !!d &&
          typeof d === "object" &&
          typeof (d as Record<string, unknown>).candidateId === "string" &&
          typeof (d as Record<string, unknown>).subject === "string" &&
          typeof (d as Record<string, unknown>).body === "string",
      )
      .map((d) => ({ candidateId: d.candidateId, subject: d.subject.slice(0, 255), body: d.body.slice(0, 5_000) }));
  } catch {
    return [];
  }
}

export async function POST(req: NextRequest) {
  const prodBlock = prodFailClosed();
  if (prodBlock) return prodBlock;

  const supabase = supabaseEnabled ? await getServerSupabase() : null;
  let userId: string | null = null;
  if (supabaseEnabled) {
    if (!supabase) return NextResponse.json({ ok: false, reason: "No Supabase client." }, { status: 500 });
    const {
      data: { user },
    } = await supabase.auth.getUser();
    if (!user) return NextResponse.json({ ok: false, reason: "Not authenticated." }, { status: 401 });
    userId = user.id;
    const { data: role } = await supabase.rpc("current_profile_role");
    if (!can(role as Role, "source")) {
      return NextResponse.json({ ok: false, reason: "Insufficient permissions." }, { status: 403 });
    }
  } else if (demoLoginEnabled) {
    // Same open-demo cost gate as /api/hermes/chat: env-resident provider keys
    // are spendable only by a caller holding a valid demo session.
    if (!demoAuthConfigured() || !verifyDemoToken(req.cookies.get(DEMO_COOKIE_NAME)?.value)) {
      return NextResponse.json({ ok: false, reason: "Sign in to use the sourcing agent." }, { status: 401 });
    }
  }

  const rl = checkRateLimit(rateLimitKey(req, "sourcing-agent", userId), { windowMs: 60_000, max: 10 });
  if (!rl.ok) return tooManyRequests(rl.retryAfterSec);

  const validated = await validateBody(req, SourcingAgentSchema, { maxBytes: 200_000 });
  if (!validated.ok) return validated.response;
  const { count = 5, provider, apiKeyId, model } = validated.data;
  const campaign = validated.data.campaign as unknown as Campaign;
  const existing = validated.data.existing as unknown as Candidate[];
  const weights: ScoringWeights = campaign?.scoringWeights;

  if (!campaign?.jobAnalysis || !weights) {
    return NextResponse.json({ ok: false, reason: "Malformed campaign payload." }, { status: 400 });
  }

  const slug = provider as AiProviderSlug;
  const vaultKey = await resolveVaultSecret(apiKeyId);
  const key = vaultKey || process.env[PROVIDER_ENV[slug]] || "";
  if (!key) {
    return NextResponse.json({ ok: false, reason: `No API key configured for ${provider}.` });
  }

  const githubToken = process.env.GITHUB_TOKEN ?? "";
  const runner = makeSourcingToolRunner(campaign, existing, weights, githubToken);
  const servers: ResolvedMcpServer[] = [
    { url: "builtin:sourcing-agent", token: "", tools: SOURCING_TOOL_DEFS, run: runner.run },
  ];

  const toolModel = model || DEFAULT_MODEL[slug];
  const prompt = buildPrompt(campaign, count);
  const result =
    slug === "anthropic"
      ? await runAnthropicWithTools({ model: toolModel, system: SYSTEM_PROMPT, prompt, key, servers, maxRounds: 6 })
      : await runOpenAiWithTools({ provider: slug, model: toolModel, system: SYSTEM_PROMPT, prompt, key, servers, maxRounds: 6 });

  const foundCandidates = runner.getFound();
  if (!result.ok) {
    // Even on a loop failure, return whatever real candidates were actually
    // found before it failed — the search itself is real and useful even
    // without a draft, same "don't throw away real work" posture as the rest
    // of this app's real-sourcing paths.
    return NextResponse.json({
      ok: foundCandidates.length > 0,
      reason: result.reason ?? "Agent loop failed.",
      candidates: foundCandidates.map((c) => ({ ...c, matchScore: c.matchScore })),
    });
  }

  const drafts = parseDrafts(result.text ?? "");
  const byId = new Map(foundCandidates.map((c) => [c.id, c]));
  // Only ever attach a draft to a candidate the tool loop actually surfaced —
  // never trust a candidateId the model invented that wasn't in a real result.
  const candidates = drafts
    .map((d) => {
      const cand = byId.get(d.candidateId);
      if (!cand) return null;
      return { ...cand, draftSubject: d.subject, draftBody: d.body };
    })
    .filter((c): c is Candidate & { draftSubject: string; draftBody: string } => c !== null);

  return NextResponse.json({ ok: true, candidates, totalFound: foundCandidates.length });
}

if (provider !== "hermes") {
  // Open-demo cost gate: env-resident provider keys are spendable ONLY by a caller
  // holding a valid demo session (admin/admin → signed httpOnly cookie). The Supabase
  // path already authenticated above; local dev (no demoLoginEnabled) stays open.
  // Fail closed if the gate secret isn't configured so the key can't leak.
  if (!supabaseEnabled && demoLoginEnabled) {
    if (!demoAuthConfigured() || !verifyDemoToken(req.cookies.get(DEMO_COOKIE_NAME)?.value)) {
      return NextResponse.json({ ok: false, reason: "Sign in to use the live model." }, { status: 401 });
    }
  }
  // Key resolution: vault by id (workspace-scoped) → env fallback → error.
  // The raw secret is NEVER logged or returned to the caller.
  const slug = provider as AiProviderSlug;
  const vaultKey = await resolveVaultSecret(keyId);
  const key = vaultKey || process.env[PROVIDER_ENV[slug]] || "";
  if (!key) {
    return NextResponse.json({ ok: false, reason: `No API key configured for ${provider}.` });
  }
  // A well-formed campaign context enables the search_candidates tool, gated by the
  // same "source" permission as /api/sourcing-agent (never for a viewer/no-permission
  // caller, even if they can reach chat).
  const campaignObj = campaign as unknown as Campaign | undefined;
  const sourcingCampaign =
    canSourceInChat && campaignObj?.jobAnalysis && campaignObj?.scoringWeights ? campaignObj : null;

  // MCP tool-calling (chat task, Anthropic): when the workspace has enabled MCP
  // servers, or web research, or a sourceable campaign is in context, let the model
  // call their tools and loop to a final answer. Additive — falls through to the
  // normal single-shot completion when no usable servers resolve.
  // Kimi Code (kimi-for-coding) rejects the OpenAI `tools` param (no function-calling),
  // so skip the tool loop for it and answer with a plain completion. Other providers
  // still get the MCP / built-in web-research / sourcing tool loop.
  // Only an admin-level caller (manage_tools) may attach MCP servers to this
  // request — a viewer/member's mcpServers array is dropped, not honored.
  const usableMcpServers = canUseMcpToolsInChat && mcpServers && mcpServers.length ? mcpServers : undefined;
  if (task === "chat" && slug !== "kimi" && (webResearch || usableMcpServers || sourcingCampaign)) {
    const resolvedServers: ResolvedMcpServer[] = [];
    // Built-in read-only web-research tools (in-process; no vault token, SSRF-guarded).
    if (webResearch) resolvedServers.push({ url: BUILTIN_WEB_URL, token: "", tools: WEB_TOOL_DEFS });
    // Compliant sourcing tool: real search (GitHub Search API / site:-scoped web
    // search), real dedupe, real deterministic scoring — never a stealth browser.
    if (sourcingCampaign) {
      const githubToken = process.env.GITHUB_TOKEN ?? "";
      const runner = makeSourcingToolRunner(
        sourcingCampaign,
        (existing ?? []) as unknown as Candidate[],
        sourcingCampaign.scoringWeights as ScoringWeights,
        githubToken,
      );
      resolvedServers.push({ url: "builtin:sourcing-chat", token: "", tools: SOURCING_TOOL_DEFS, run: runner.run });
    }
    if (usableMcpServers) resolvedServers.push(...(await gatherMcpServers(usableMcpServers)));
    if (resolvedServers.length) {
      const toolModel = model && model !== "hermes" ? model : DEFAULT_MODEL[slug];
      const result =
        slug === "anthropic"
          ? await runAnthropicWithTools({ model: toolModel, system, prompt, key, servers: resolvedServers })
          : await runOpenAiWithTools({ provider: slug, model: toolModel, system, prompt, key, servers: resolvedServers });
      if (result.ok && result.text) return NextResponse.json({ ok: true, text: result.text });
      // Tool loop failed or returned empty (e.g. a provider that rejects the tools
      // param) → fall through to a normal single-shot completion so chat still answers
      // instead of erroring out / dropping the caller to the client-side mock.
      if (!result.ok) logUpstream("info", "Tool loop unavailable; using plain completion", { provider, reason: result.reason });
    }
  }
  const { url, headers, body } = buildCloudRequest(slug, model ?? "hermes", system, prompt, key);
  try {
    const upstream = await fetch(url, {
      method: "POST",
      headers,
      body,
      // SSRF hardening: never auto-follow upstream redirects.
      redirect: "manual",
      signal: AbortSignal.timeout(UPSTREAM_TIMEOUT_MS),
    });
    if (isRedirectResponse(upstream)) {
      logUpstream("error", "Blocked cloud provider redirect", { provider, status: upstream.status });
      return NextResponse.json({ ok: false, reason: "Upstream redirect blocked (SSRF guard)." });
    }
    if (!upstream.ok) {
      logUpstream("error", "Cloud provider upstream error", { provider, status: upstream.status });
      return NextResponse.json({ ok: false, reason: `Upstream error ${upstream.status}` });
    }
    const json = await upstream.json().catch(() => null);
    const text = parseCloudResponse(slug, json);
    if (!text) {
      return NextResponse.json({ ok: false, reason: "Empty response from provider." });
    }
    return NextResponse.json({ ok: true, text });
  } catch (err) {
    const msg = err instanceof Error ? err.message : "Network error.";
    logUpstream("error", "Cloud provider network error", { provider, error: msg });
    return NextResponse.json({ ok: false, reason: redactSecrets(redactEmail(msg)) });
  }
}

const production = process.env.NODE_ENV === "production";
let runtimeWorkspaceId: string | null = null;
if (production && supabaseEnabled && supabase) {
  const { data: resolvedWorkspaceId, error: workspaceError } = await supabase.rpc("current_workspace_id");
  runtimeWorkspaceId = typeof resolvedWorkspaceId === "string" ? resolvedWorkspaceId : null;
  if (workspaceError || !runtimeWorkspaceId) {
    return NextResponse.json({ ok: false, reason: "Workspace not available." }, { status: 403 });
  }
}
const binding = evaluateHermesWorkspaceBinding({
  production,
  supabaseEnabled,
  workspaceId: runtimeWorkspaceId,
  boundWorkspaceId: process.env.HERMES_RUNTIME_WORKSPACE_ID,
});
if (!binding.ok) {
  return NextResponse.json({ ok: false, reason: binding.reason }, { status: binding.status });
}

// S-1: URL is env-only — never use client-supplied hermesApiUrl (SSRF risk).
const rawBaseUrl = process.env.HERMES_API_URL ?? "";
const baseUrl = rawBaseUrl.replace(/\/$/, "");
if (!baseUrl) {
  return NextResponse.json({ ok: false, reason: "Aria runtime URL is not configured." });
}
const urlCheck = isAllowedHermesUrl(baseUrl);
if (!urlCheck.ok) {
  logUpstream("error", "Blocked Aria URL due to SSRF policy", { url: baseUrl, reason: urlCheck.reason });
  return NextResponse.json({ ok: false, reason: `Aria runtime URL rejected: ${urlCheck.reason}` });
}

// Resolve the bearer token server-side. Vault by id (workspace-scoped) first;
// env fallback is allowed only when no key id was requested. A supplied id
// that does not resolve in this workspace must fail closed.
let bearerToken = process.env.HERMES_API_KEY ?? "";
if (hermesApiKeyId) {
  const vaultSecret = await resolveVaultSecret(hermesApiKeyId);
  if (!vaultSecret) {
    return NextResponse.json({ ok: false, reason: "Aria runtime key is not available." }, { status: 403 });
  }
  bearerToken = vaultSecret;
}

const headers: Record<string, string> = { "Content-Type": "application/json" };
if (bearerToken) headers["Authorization"] = `Bearer ${bearerToken}`;

import { NextResponse, type NextRequest } from "next/server";
import { z } from "zod";
import { getServerSupabase } from "@/lib/supabase/server";
import { supabaseEnabled, prodFailClosed, demoLoginEnabled, DEMO_COOKIE_NAME } from "@/lib/supabase/config";
import { demoAuthConfigured, verifyDemoToken } from "@/lib/demo-auth";
import { validateBody } from "@/lib/api/validate";
import { can } from "@/lib/rbac";
import type { Campaign, Candidate, Role, ScoringWeights } from "@/lib/types";
import { DEFAULT_MODEL, PROVIDER_ENV, buildCloudRequest, parseCloudResponse, type AiProviderSlug } from "@/lib/ai/provider";
import { resolveVaultSecret } from "@/lib/ai/vault-secret";
import { makeSourcingToolRunner } from "@/lib/ai/sourcing-tools";
import { checkRateLimit, rateLimitKey, tooManyRequests } from "@/lib/rate-limit";
import { initialState, runGraph, type CandidateLite, type GraphDeps } from "@/lib/agents/graph";

export const dynamic = "force-dynamic";

/**
 * On-demand sourcing agent run — the deer-flow-style graph
 * (planner → sourcer → screener → outreach → reporter) over the same real
 * search + deterministic scoring the single-shot /api/sourcing-agent uses.
 *
 * Same posture as that route: TEXT + SEARCH ONLY — this never sends anything;
 * gate-passing drafts still require the human approval gate (or gated
 * autopilot's system approval) before /api/outreach/send will touch the wire.
 *
 * With Supabase configured, every node persists to agent_runs (resumable) and
 * narrates to agent_events (append-only, no send path). In demo mode the run
 * executes statelessly and just returns its result.
 */
const AGENT_PROVIDERS = ["anthropic", "openai", "groq", "xai", "mistral"] as const;

const AgentRunSchema = z.object({
  campaign: z.record(z.string(), z.unknown()),
  existing: z.array(z.record(z.string(), z.unknown())).max(500).default([]),
  count: z.number().int().min(1).max(8).default(5),
  provider: z.enum(AGENT_PROVIDERS),
  apiKeyId: z.string().uuid().optional(),
  model: z.string().regex(/^[a-zA-Z0-9][a-zA-Z0-9._-]{0,79}$/).optional(),
  specId: z.string().uuid().optional(),
});

export async function POST(req: NextRequest) {
  const prodBlock = prodFailClosed();
  if (prodBlock) return prodBlock;

  const supabase = supabaseEnabled ? await getServerSupabase() : null;
  let workspaceId: string | null = null;
  let userId: string | null = null;
  if (supabaseEnabled) {
    if (!supabase) return NextResponse.json({ ok: false, reason: "No Supabase client." }, { status: 500 });
    const {
      data: { user },
    } = await supabase.auth.getUser();
    if (!user) return NextResponse.json({ ok: false, reason: "Not authenticated." }, { status: 401 });
    userId = user.id;
    const { data: role } = await supabase.rpc("current_profile_role");
    if (!can(role as Role, "source")) {
      return NextResponse.json({ ok: false, reason: "Insufficient permissions." }, { status: 403 });
    }
    const { data: wid } = await supabase.rpc("current_workspace_id");
    workspaceId = (wid as string) ?? null;
  } else if (demoLoginEnabled) {
    if (!demoAuthConfigured() || !verifyDemoToken(req.cookies.get(DEMO_COOKIE_NAME)?.value)) {
      return NextResponse.json({ ok: false, reason: "Sign in to run agents." }, { status: 401 });
    }
  }

  const rl = checkRateLimit(rateLimitKey(req, "agents-run", userId), { windowMs: 60_000, max: 6 });
  if (!rl.ok) return tooManyRequests(rl.retryAfterSec);

  const validated = await validateBody(req, AgentRunSchema, { maxBytes: 200_000 });
  if (!validated.ok) return validated.response;
  const { count = 5, provider, apiKeyId, model, specId } = validated.data;
  const campaign = validated.data.campaign as unknown as Campaign;
  const existing = validated.data.existing as unknown as Candidate[];
  const weights: ScoringWeights = campaign?.scoringWeights;
  if (!campaign?.jobAnalysis || !weights) {
    return NextResponse.json({ ok: false, reason: "Malformed campaign payload." }, { status: 400 });
  }

  const slug = provider as AiProviderSlug;
  const vaultKey = await resolveVaultSecret(apiKeyId);
  const key = vaultKey || process.env[PROVIDER_ENV[slug]] || "";
  if (!key) return NextResponse.json({ ok: false, reason: `No API key configured for ${provider}.` });
  const llmModel = model || DEFAULT_MODEL[slug];

  const runner = makeSourcingToolRunner(campaign, existing, weights, process.env.GITHUB_TOKEN ?? "");
  const deps: GraphDeps = {
    async generate(system, prompt) {
      const reqSpec = buildCloudRequest(slug, llmModel, system, prompt, key, 1024);
      const res = await fetch(reqSpec.url, {
        method: "POST",
        headers: reqSpec.headers,
        body: reqSpec.body,
        signal: AbortSignal.timeout(45_000),
      });
      if (!res.ok) throw new Error(`${provider} ${res.status}`);
      return parseCloudResponse(slug, await res.json());
    },
    async search(platform, query, searchCount) {
      const before = runner.getFound().length;
      await runner.run("search_candidates", { platform, query, count: searchCount });
      return runner
        .getFound()
        .slice(before)
        .map((c) => ({
          id: c.id,
          name: c.name,
          matchScore: c.matchScore,
          currentTitle: c.currentTitle,
          currentCompany: c.currentCompany,
        })) as CandidateLite[];
    },
  };

  // Persistent run row (when the backend exists) — resumable + auditable.
  let runId: string | null = null;
  if (supabase && workspaceId) {
    const { data: run } = await supabase
      .from("agent_runs")
      .insert({ spec_id: specId ?? null, workspace_id: workspaceId, state_json: {}, node: "planner" })
      .select("id")
      .maybeSingle();
    runId = run?.id ?? null;
  }

  const state = initialState(campaign.jobAnalysis as unknown as Record<string, unknown>, count);
  const result = await runGraph(state, deps, async (node, s, event) => {
    if (!supabase || !workspaceId || !runId) return;
    await supabase
      .from("agent_runs")
      .update({
        node,
        state_json: s as unknown as Record<string, unknown>,
        step_count: s.drafts.length + s.planCursor,
        status: node === "done" ? "done" : "running",
        ...(node === "done" ? { finished_at: new Date().toISOString() } : {}),
      })
      .eq("id", runId);
    await supabase
      .from("agent_events")
      .insert({ run_id: runId, workspace_id: workspaceId, type: event.type, payload: event.payload });
  });

  const found = runner.getFound();
  const byId = new Map(found.map((c) => [c.id, c]));
  const candidates = result.state.drafts
    .filter((d) => d.gatePassed)
    .map((d) => {
      const cand = byId.get(d.candidateId);
      return cand ? { ...cand, draftSubject: d.subject, draftBody: d.body } : null;
    })
    .filter((c): c is Candidate & { draftSubject: string; draftBody: string } => c !== null);

  return NextResponse.json({
    ok: true,
    runId,
    report: result.state.report ?? "",
    candidates,
    totalFound: found.length,
    heldByGate: result.state.drafts.filter((d) => !d.gatePassed).length,
    errors: result.state.errors,
  });
}

